-- @seq 417
CREATE FUNCTION public.erp_decide_return(p_rma_id uuid, p_approve boolean, p_reason text DEFAULT NULL::text, p_lines jsonb DEFAULT NULL::jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE r erp_return_authorizations%ROWTYPE;
BEGIN
  SELECT * INTO r FROM erp_return_authorizations WHERE id = p_rma_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Return not found'; END IF;
  PERFORM acct_assert_access(r.tenant_id);
  IF lower(r.status) NOT IN ('requested','pending','open','submitted','draft') THEN RAISE EXCEPTION 'Return is already %', r.status; END IF;
  IF NOT p_approve AND (p_reason IS NULL OR btrim(p_reason) = '') THEN RAISE EXCEPTION 'A reason is required to decline a return'; END IF;
  IF p_approve THEN
    UPDATE erp_return_lines l SET quantity_approved = coalesce(
             (SELECT (x->>'quantity')::numeric FROM jsonb_array_elements(p_lines) x WHERE (x->>'return_line_id')::uuid = l.id), l.quantity_requested)
     WHERE l.rma_id = r.id;
  ELSE
    UPDATE erp_return_lines SET quantity_approved = 0 WHERE rma_id = r.id;
  END IF;
  UPDATE erp_return_authorizations SET status = CASE WHEN p_approve THEN 'approved' ELSE 'declined' END,
         approved_at = CASE WHEN p_approve THEN now() END,
         notes = concat_ws(E'\n', notes, CASE WHEN p_reason IS NOT NULL THEN CASE WHEN p_approve THEN 'Approved: ' ELSE 'Declined: ' END || p_reason END),
         updated_at = now()
   WHERE id = r.id;
  RETURN CASE WHEN p_approve THEN 'approved' ELSE 'declined' END;
END $$;

-- @seq 421
CREATE FUNCTION public.erp_open_return(p_order_id uuid, p_lines jsonb, p_reason_code text DEFAULT NULL::text, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE o erp_orders%ROWTYPE; v uuid; x jsonb; ol erp_order_lines%ROWTYPE; v_qty numeric; v_sku uuid; v_open numeric;
BEGIN
  SELECT * INTO o FROM erp_orders WHERE id = p_order_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Order not found'; END IF;
  PERFORM acct_assert_access(o.tenant_id);
  IF jsonb_typeof(p_lines) <> 'array' OR jsonb_array_length(p_lines) = 0 THEN RAISE EXCEPTION 'Choose at least one line to return'; END IF;
  INSERT INTO erp_return_authorizations(tenant_id, rma_number, order_id, crm_customer_id, status, reason_code, requested_at, notes, created_by)
  VALUES (o.tenant_id, erp_next_document_number(o.tenant_id, 'rma'), o.id, o.crm_customer_id, 'requested', p_reason_code, now(), p_notes, auth.uid())
  RETURNING id INTO v;
  FOR x IN SELECT value FROM jsonb_array_elements(p_lines) LOOP
    SELECT * INTO ol FROM erp_order_lines WHERE id = (x->>'order_line_id')::uuid AND order_id = o.id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Line % is not on order %', x->>'order_line_id', o.order_number; END IF;
    v_qty := coalesce((x->>'quantity')::numeric, ol.quantity_shipped, ol.quantity);
    SELECT coalesce(sum(rl.quantity_requested),0) INTO v_open FROM erp_return_lines rl JOIN erp_return_authorizations ra ON ra.id = rl.rma_id
     WHERE rl.order_line_id = ol.id AND ra.status NOT IN ('declined','cancelled','completed') AND ra.id <> v;
    IF v_qty <= 0 OR v_qty + v_open + coalesce(ol.quantity_returned,0) > ol.quantity THEN
      RAISE EXCEPTION 'Cannot return % of % on line % (% already returned or pending)', v_qty, ol.quantity, coalesce(ol.description, ol.id::text), coalesce(ol.quantity_returned,0) + v_open;
    END IF;
    v_sku := coalesce(erp__sku_for_variant(o.tenant_id, ol.sku_id), (x->>'sku_id')::uuid);
    IF v_sku IS NULL THEN RAISE EXCEPTION 'Line % has no warehouse SKU; map the variant to an ERP SKU first', coalesce(ol.description, ol.id::text); END IF;
    INSERT INTO erp_return_lines(tenant_id, rma_id, order_line_id, sku_id, quantity_requested, disposition, refund_amount)
    VALUES (o.tenant_id, v, ol.id, v_sku, v_qty, coalesce(x->>'disposition', 'restock'),
            coalesce((x->>'refund_amount')::numeric, round(coalesce(ol.line_total, ol.unit_price * ol.quantity) / NULLIF(ol.quantity,0) * v_qty, 2)));
  END LOOP;
  RETURN v;
END $$;

-- @seq 425
CREATE FUNCTION public.erp_receive_return(p_rma_id uuid, p_lines jsonb DEFAULT NULL::jsonb, p_refund boolean DEFAULT true, p_warehouse_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE r erp_return_authorizations%ROWTYPE; l record; v_qty numeric; v_wh uuid; v_loc uuid; v_refund numeric := 0; v_restocked numeric := 0; v_disp text;
BEGIN
  SELECT * INTO r FROM erp_return_authorizations WHERE id = p_rma_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Return not found'; END IF;
  PERFORM acct_assert_access(r.tenant_id);
  IF r.status <> 'approved' THEN RAISE EXCEPTION 'Approve the return before receiving it (status is %)', r.status; END IF;
  v_wh := coalesce(p_warehouse_id, erp__default_warehouse(r.tenant_id));
  v_loc := CASE WHEN v_wh IS NOT NULL THEN erp__default_location(r.tenant_id, v_wh) END;
  FOR l IN SELECT * FROM erp_return_lines WHERE rma_id = r.id AND coalesce(quantity_approved,0) > 0 LOOP
    v_qty := coalesce((SELECT (x->>'quantity')::numeric FROM jsonb_array_elements(coalesce(p_lines,'[]'::jsonb)) x WHERE (x->>'return_line_id')::uuid = l.id),
                      l.quantity_approved - coalesce(l.quantity_received,0));
    v_disp := coalesce((SELECT x->>'disposition' FROM jsonb_array_elements(coalesce(p_lines,'[]'::jsonb)) x WHERE (x->>'return_line_id')::uuid = l.id), l.disposition, 'restock');
    IF v_qty <= 0 THEN CONTINUE; END IF;
    IF v_qty + coalesce(l.quantity_received,0) > l.quantity_approved THEN RAISE EXCEPTION 'Received more than approved on a return line'; END IF;
    IF v_disp = 'restock' THEN
      IF v_wh IS NULL THEN RAISE EXCEPTION 'No warehouse to restock into'; END IF;
      PERFORM erp__move(r.tenant_id, 'return', l.sku_id, v_wh, v_loc, v_qty, NULL, 'erp_return_authorizations', r.id, r.rma_number, 'Customer return');
      v_restocked := v_restocked + v_qty;
    ELSIF v_disp IN ('damage','scrap') THEN
      NULL;  -- not resellable: no stock movement into available inventory
    END IF;
    UPDATE erp_return_lines SET quantity_received = coalesce(quantity_received,0) + v_qty, disposition = v_disp WHERE id = l.id;
    UPDATE erp_order_lines SET quantity_returned = coalesce(quantity_returned,0) + v_qty, updated_at = now() WHERE id = l.order_line_id;
    v_refund := v_refund + round(coalesce(l.refund_amount,0) / NULLIF(l.quantity_requested,0) * v_qty, 2);
  END LOOP;
  UPDATE erp_return_authorizations SET received_at = now(),
         status = CASE WHEN EXISTS (SELECT 1 FROM erp_return_lines WHERE rma_id = r.id AND coalesce(quantity_received,0) < coalesce(quantity_approved,0))
                       THEN 'approved' ELSE 'completed' END,
         completed_at = CASE WHEN NOT EXISTS (SELECT 1 FROM erp_return_lines WHERE rma_id = r.id AND coalesce(quantity_received,0) < coalesce(quantity_approved,0))
                             THEN now() END,
         updated_at = now()
   WHERE id = r.id;
  IF p_refund AND v_refund > 0 AND r.order_id IS NOT NULL THEN
    PERFORM erp_refund_order(r.order_id, v_refund, 'Return ' || r.rma_number, r.id);
  END IF;
  RETURN jsonb_build_object('restocked', v_restocked, 'refunded', CASE WHEN p_refund THEN v_refund ELSE 0 END);
END $$;

-- @seq 428
CREATE FUNCTION public.erp_refund_order(p_order_id uuid, p_amount numeric, p_reason text, p_rma_id uuid DEFAULT NULL::uuid) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE o erp_orders%ROWTYPE; v_amt numeric := round(p_amount, 2);
BEGIN
  SELECT * INTO o FROM erp_orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Order not found'; END IF;
  PERFORM acct_assert_access(o.tenant_id);
  IF v_amt IS NULL OR v_amt <= 0 THEN RAISE EXCEPTION 'Refund amount must be positive'; END IF;
  IF p_reason IS NULL OR btrim(p_reason) = '' THEN RAISE EXCEPTION 'A refund reason is required'; END IF;
  IF coalesce(o.amount_refunded,0) + v_amt > coalesce(o.amount_paid,0) THEN
    RAISE EXCEPTION 'Refunds (% + %) would exceed the % paid on order %', coalesce(o.amount_refunded,0), v_amt, coalesce(o.amount_paid,0), o.order_number;
  END IF;
  UPDATE erp_orders SET amount_refunded = coalesce(amount_refunded,0) + v_amt, updated_at = now(),
         metadata = coalesce(metadata,'{}'::jsonb) || jsonb_build_object('last_refund', jsonb_build_object('amount', v_amt, 'reason', p_reason, 'at', now(), 'rma_id', p_rma_id))
   WHERE id = o.id;
  IF p_rma_id IS NOT NULL THEN
    INSERT INTO erp_return_refunds(tenant_id, rma_id, amount, currency, status, processed_at) VALUES (o.tenant_id, p_rma_id, v_amt, o.currency, 'completed', now());
  END IF;
  RETURN coalesce(o.amount_refunded,0) + v_amt;
END $$;

